#:package System.IdentityModel.Tokens.Jwt@8.3.0
using System.IdentityModel.Tokens.Jwt;
using Microsoft.IdentityModel.Tokens;
var key = new SymmetricSecurityKey(new byte[32]);
var handler = new JwtSecurityTokenHandler();
string Check(int minutesAgo) {
  var now = DateTime.UtcNow;
  var t = new JwtSecurityToken(notBefore: now.AddMinutes(-minutesAgo - 15), expires: now.AddMinutes(-minutesAgo),
     signingCredentials: new SigningCredentials(key, SecurityAlgorithms.HmacSha256));
  try { handler.ValidateToken(handler.WriteToken(t), new TokenValidationParameters {
      ValidateIssuer = false, ValidateAudience = false, IssuerSigningKey = key }, out _); return "valid"; }
  catch (SecurityTokenExpiredException) { return "expired"; }
}
foreach (var m in new[] { -5, 4, 6 })
    Console.WriteLine(Check(m));

#:sdk Microsoft.NET.Sdk.Web
using Microsoft.Extensions.Diagnostics.HealthChecks;
using Microsoft.AspNetCore.Diagnostics.HealthChecks;
var builder = WebApplication.CreateBuilder(args);
builder.WebHost.UseUrls("http://127.0.0.1:0");
builder.Logging.ClearProviders();
builder.Services.AddHealthChecks()
    .AddCheck("self", () => HealthCheckResult.Healthy(),
        tags: ["live"])
    .AddCheck("db", () => HealthCheckResult.Unhealthy("down"),
        tags: ["ready"]);

var app = builder.Build();
app.MapHealthChecks("/health/live", new HealthCheckOptions
{ Predicate = c => c.Tags.Contains("live") });
app.MapHealthChecks("/health/ready", new HealthCheckOptions
{ Predicate = c => c.Tags.Contains("ready") });
app.MapHealthChecks("/health/all");
await app.StartAsync();
using var http = new HttpClient();
foreach (var p in new[] { "live", "ready", "all" })
    Console.WriteLine(p + " " + (int)(await http.GetAsync(app.Urls.First() + "/health/" + p)).StatusCode);
await app.StopAsync();

